/** A dictionary change during an actual replacement-domain commit cannot be certified as a paired generation. */
@Timeout(90)
class LmdbDeferredDomainPublicationForeignWriterTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:domain-publish-foreign:subject");
	private static final IRI P = VF.createIRI("urn:domain-publish-foreign:predicate");
	private static final IRI O = VF.createIRI("urn:domain-publish-foreign:object");
	private static final List<LmdbStore> RETAINED_OPEN_STORES = new CopyOnWriteArrayList<>();

	@Test
	void dictionaryCommitBetweenDomainScanAndNativeCommitCannotPublishAuthority(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		long predicateId = seedUnqualifiedStore(directory);
		Gate gate = new Gate(predicateId);
		LmdbStore store = instrumentedStore(directory, gate);
		ExecutorService initializer = Executors.newSingleThreadExecutor(Thread.ofPlatform().daemon().factory());
		AtomicBoolean childSettled = new AtomicBoolean(true);
		AtomicReference<Future<?>> opening = new AtomicReference<>();
		try (AutoCloseable cleanup = () -> {
			gate.release.countDown();
			initializer.shutdown();
			Future<?> task = opening.get();
			if ((task == null || task.isDone()) && childSettled.get()) {
				store.shutDown();
				assertTrue(initializer.awaitTermination(30, TimeUnit.SECONDS));
			} else {
				RETAINED_OPEN_STORES.add(store);
				throw new IllegalStateException("Live initialization/child owner retained with fixture " + evidence);
			}
		}) {
			opening.set(initializer.submit(store::init));
			assertTrue(gate.entered.await(30, TimeUnit.SECONDS),
					"the real replacement-domain scan must reach its native commit");
			childSettled.set(false);
			runForeignWriter(directory, evidence, childSettled);
			gate.release.countDown();
			Throwable openFailure = null;
			try {
				opening.get().get(30, TimeUnit.SECONDS);
			} catch (ExecutionException failure) {
				openFailure = failure.getCause();
			}
			if (openFailure != null) {
				assertTrue(causeText(openFailure).contains("intervening native"),
						"only a recognized foreign-writer refusal is a safe startup outcome: " + openFailure);
			} else {
				try {
					LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
				} catch (IOException maintenanceFailure) {
					assertTrue(store.getStartupStatus().auxiliaryMaintenance().startsWith("FAILED"),
							"a deferred failure must be visible in maintenance status");
				}
				LmdbSailStore backing = store.getBackingStore();
				TripleStore triples = backing.getTripleStore();
				assertNull(triples.completeRdfTermDomainVersion(),
						"the global domain qualification must remain withheld");
				LmdbEstimatorRuntime runtime = assertInstanceOf(LmdbEvaluationStatistics.class,
						store.getSailStore().getEvaluationStatistics()).estimatorRuntime();
				try (LmdbSailStore.DatasetAdmission admission = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
					LmdbSailStore.ReadView view = admission.view();
					view.requireDictionaryTermSnapshot();
					try (TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.tripleTxn(), view.valueSnapshot())) {
						assertFalse(triples.getKnownRdfTermDomain(gate.predicateId).isPresent(),
								"the admitted paired planner cannot use a foreign dictionary generation");
					}
				}
				try (var connection = store.getConnection()) {
					assertTrue(connection.hasStatement(S, P, O, false), "the authoritative statement must survive");
				}
			}
		}
	}

	private static LmdbStore instrumentedStore(Path directory, Gate gate) {
		return new LmdbStore(directory.toFile(), config()) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig config,
					boolean estimatorEnabled) throws IOException, SailException {
				return new LmdbSailStore(dataDir, properties, config, estimatorEnabled,
						(valueDir, valueProperties, valueConfig) -> new ValueStore(valueDir, valueProperties, valueConfig),
						(tripleDir, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDir,
								tripleProperties, tripleConfig, values) {
							@Override
							int commitDeferredDomainNativeWriter(long transaction,
									RetirementNativeTransaction nativeOwner) throws IOException {
								if (gate.first.compareAndSet(true, false)) {
										assertTrue(nativeOwner.canAbort(), "the actual domain writer must be owned on this thread");
										assertEquals(RdfTermDomain.IRI, pendingDomain(transaction, gate.predicateId),
												"the held native writer must contain the rebuilt IRI domain");
										gate.entered.countDown();
										try {
											if (!gate.release.await(30, TimeUnit.SECONDS)) {
												throw new AssertionError("domain commit gate was not released");
											}
										} catch (InterruptedException interrupted) {
											Thread.currentThread().interrupt();
											throw new AssertionError("domain commit gate interrupted", interrupted);
										}
								}
								return super.commitDeferredDomainNativeWriter(transaction, nativeOwner);
							}
						});
			}
		};
	}

	private static long seedUnqualifiedStore(Path directory) throws Exception {
		LmdbStore seed = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(seed);
		long predicateId;
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, P, O);
				connection.commit();
			}
			predicateId = ((ValueStore) seed.getBackingStore().getValueFactory()).getId(P);
		} finally {
			repository.shutDown();
		}
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		properties.setRdfTermDomainsVersion("test-obsolete-domain-profile");
		properties.save();
		return predicateId;
	}

	private static RdfTermDomain pendingDomain(long transaction, long predicateId) {
		try (MemoryStack stack = stackPush()) {
			var dbi = stack.mallocInt(1);
			assertEquals(MDB_SUCCESS, mdb_dbi_open(transaction, TripleStore.PREDICATE_OBJECT_DOMAINS_DB, 0, dbi));
			ByteBuffer bytes = stack.malloc(9);
			Varint.writeUnsigned(bytes, predicateId);
			bytes.flip();
			MDBVal key = MDBVal.malloc(stack).mv_data(bytes);
			MDBVal data = MDBVal.malloc(stack);
			assertEquals(MDB_SUCCESS, mdb_get(transaction, dbi.get(0), key, data));
			ByteBuffer record = data.mv_data();
			assertTrue(record.remaining() >= 2 * Long.BYTES);
			return RdfTermDomain.fromMask(record.getLong(record.position() + Long.BYTES));
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false).setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF).setPredicateGuaranteeIndexEnabled(true)
				.setPredicateGuaranteeIndexAutoRebuild(true).setForceSync(true);
	}

	private static void runForeignWriter(Path directory, Path evidence, AtomicBoolean settled) throws Exception {
		Path temporary = evidence.resolve("child-tmp");
		Files.createDirectory(temporary);
		Path log = evidence.resolve("foreign-dictionary-writer.log");
		Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"--enable-native-access=ALL-UNNAMED", "-ea", "-Djava.io.tmpdir=" + temporary,
				"-cp", System.getProperty("java.class.path"),
				LmdbDeferredDomainForeignWriterTest.ForeignWriter.class.getName(), directory.toString())
						.redirectErrorStream(true).redirectOutput(log.toFile()).start();
		if (!child.waitFor(30, TimeUnit.SECONDS)) {
			throw new AssertionError("foreign writer did not settle; retained child and store: " + log);
		}
		settled.set(true);
		String output = Files.readString(log);
		assertEquals(0, child.exitValue(), () -> "foreign writer failed: " + output);
		assertTrue(output.contains("FOREIGN_DICTIONARY_COMMITTED"), "the real native commit must be reached");
	}

	private static String causeText(Throwable failure) {
		StringBuilder result = new StringBuilder();
		for (Throwable current = failure; current != null; current = current.getCause()) {
			result.append(current).append('\n');
		}
		return result.toString();
	}

	private static final class Gate {
		private final long predicateId;
		private final AtomicBoolean first = new AtomicBoolean(true);
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);

		private Gate(long predicateId) {
			this.predicateId = predicateId;
		}
	}
}
